    var l=(j.models||[]).filter(function(m){return /flash/i.test(m.name)&&!/(lite|image|tts|live|audio|thinking|exp|preview|embedding|robotics)/i.test(m.name)&&(m.supportedGenerationMethods||[]).indexOf('generateContent')>-1}).map(function(m){return m.name.replace('models/','')});
    l.sort(function(a,b){return parseFloat((b.match(/\d+(\.\d+)?/)||[0])[0])-parseFloat((a.match(/\d+(\.\d+)?/)||[0])[0])});
