function apiSteps(d){
  var win=d==='windows',sep=win?'; ':' && ';
  var R='https://github.com/public-apis/public-apis',T='https://api.open-meteo.com/v1/forecast?latitude=30.04&longitude=31.24&current_weather=true';
  return [
   {t:'ما هو مشروع Public APIs',d:'المشروع قائمة مفتوحة المصدر ومنسقة بآلاف الجهد من المساهمين، تجمع واجهات برمجية (APIs) مجانية مصنفة حسب المجال: طقس، أخبار، عملات، ذكاء اصطناعي، أمن، ألعاب وغيرها. هو ليس مكتبة تُثبَّت ولا خدمة بعينها، وإنما ملف README.md فيه جدول لكل API رابطه ووصفه وطريقة المصادقة. تستخدمه لتجد API مناسبًا ثم تتعامل مع مزوده مباشرة.',l:R},
   {t:'تجهيز Git',d:'نحتاج Git لنسخ المستودع. لو نفذت خطوات الإعداد الأساسية لجهازك فهو مثبّت. تحقق من ذلك بالأمر التالي، وإن لم يظهر رقم إصدار ثبّته أولًا من صفحة الإعداد الأخرى. وبدون Git يمكنك فتح الرابط وتحميل ZIP من زر Code ثم Download ZIP.',c:'git --version'},
   {t:'نسخ المستودع إلى جهازك',d:'ينسخ الأمر كل الملفات إلى مجلد public-apis ثم ندخل إليه. الحجم صغير لأنه نصوص في الغالب.',c:'git clone '+R+'.git'+sep+'cd public-apis'},
   {t:'فهم الجدول',d:'افتح README.md. كل صف فيه خمسة أعمدة: API وهو الاسم والرابط، وDescription وهو الوصف، وAuth وهو نوع المصادقة (No يعني بلا مفتاح، وapiKey يعني مفتاحًا، وOAuth يعني تسجيل دخول)، وHTTPS هل يدعم اتصالًا آمنًا، وCORS هل يسمح باستدعائه من المتصفح مباشرة (Yes أو No أو Unknown).'},
   {t:'البحث عن API بالكلمة',d:'بدل التمرير في الملف الطويل ابحث بكلمة تخص حاجتك، مثل weather أو currency أو news. الأمر يعرض الصفوف المطابقة فقط.',c:win?'Select-String -Path README.md -Pattern "weather"':'grep -i "weather" README.md'},
   {t:'تصفية الأنسب للبداية',d:'ابدأ بما لا يحتاج مفتاحًا ويدعم HTTPS لأنه أسرع تجربة وأقل أخطاء. هذا الأمر يعرض صفوف الطقس التي مصادقتها No وHTTPS فيها Yes.',c:win?'Select-String -Path README.md -Pattern "weather" | Where-Object { $_.Line -match "\\| No \\| Yes \\|" }':'grep -i "weather" README.md | grep "| No | Yes |"'},
   {t:'اختيار API بشكل صحيح',d:'قبل الاعتماد على أي API افتح صفحته وتحقق من: حدود الاستخدام (Rate Limit)، وشروط الاستخدام والترخيص خصوصًا للمشاريع التجارية، واستمرار الخدمة وآخر تحديث لها. لو ستستدعيه من صفحة ويب فاختر CORS = Yes، وإلا ستحتاج وسيطًا على خادم.'},
   {t:'الحصول على مفتاح عند الحاجة',d:'لو كانت المصادقة apiKey: افتح رابط المزود، أنشئ حسابًا، ثم أنشئ مفتاحًا من لوحته. لا تكتب المفتاح داخل كود صفحة عامة ولا ترفعه إلى GitHub. خزّنه في متغير بيئة كما في الأمر، ثم أعد فتح الطرفية.',c:win?'setx MY_API_KEY "ضع_المفتاح_هنا"':'export MY_API_KEY="ضع_المفتاح_هنا"'},
   {t:'تجربة API من الطرفية',d:'جرّب Open-Meteo كمثال، وهو API طقس بلا مفتاح ومذكور في القائمة. الأمر يعيد حالة الطقس الحالية لإحداثيات القاهرة بصيغة JSON. إن ظهر JSON فالتجربة نجحت.',c:(win?'curl.exe "':'curl "')+T+'"'},
   {t:'استخدامه في صفحة ويب',d:'افتح أي صفحة في المتصفح واضغط F12 ثم تبويب Console والصق السطر التالي. يجلب الطقس ويطبعه. هذا يعمل فقط إن كان الـ API يسمح بـ CORS.',c:"fetch('"+T+"').then(function(r){return r.json()}).then(console.log)"},
   {t:'توثيق ما تعلمته في مقال',d:'من لوحة الإدارة أضف المقال وادرج الكود عبر خيار إضافة كود برمجي، مع شرح الأسطر بالألوان. بهذا يصبح لموقعك مرجع خاص بالـ APIs التي جرّبتها.'},
   {t:'تحديث القائمة والمساهمة',d:'القائمة تتغير باستمرار، فحدّثها من وقت لآخر من داخل مجلد المشروع. وإن وجدت API متوقفًا أو أردت إضافة واحد جديد فاقرأ ملف CONTRIBUTING في المستودع ثم افتح Pull Request.',c:'git pull'}
  ];
}
async function gCall(contents,system){
  var bd=JSON.stringify({system_instruction:{parts:[{text:system}]},contents:contents});
  var first=AUTOM||((GM&&!/^gemini-(1|2)/.test(GM))?GM:DEFM),r,j;
  async function tryM(m){r=await gem(m,bd);j=await r.json();return r.ok}
  var ok=await tryM(first);
  if(!ok&&r.status!==401&&r.status!==403&&!/api key|API_KEY/i.test(JSON.stringify(j.error||{}))){
    try{MODELS=MODELS||await gModels(GK)}catch(e){MODELS=[]}
    var n=0;for(var i=0;i<MODELS.length&&n<4&&!ok;i++){if(MODELS[i]===first)continue;n++;ok=await tryM(MODELS[i]);if(ok)AUTOM=MODELS[i]}
  }
  if(!ok)throw new Error((j.error&&j.error.message)||('HTTP '+r.status));
  var cd=j.candidates&&j.candidates[0],t=((cd&&cd.content&&cd.content.parts)||[]).map(function(p){return p.text||''}).join('');
  if(!t)t=(j.promptFeedback&&j.promptFeedback.blockReason)?'تم حجب الطلب من Gemini: '+j.promptFeedback.blockReason:'لم أحصل على رد'+(cd&&cd.finishReason?' ('+cd.finishReason+')':'');
  return t;
}
