function fmtSize(b){var m=b/1048576;return (m>=100?m.toFixed(0):m.toFixed(1))+' MB'}
async function apkMeta(url){
  var o={size:0,downloads:0};
  var m=String(url||'').match(/^https:\/\/github\.com\/([^\/]+)\/([^\/]+)\/releases\/download\/([^\/]+)\/([^\/?#]+)/i);
  try{
    if(m){
      var r=await fetch('https://api.github.com/repos/'+m[1]+'/'+m[2]+'/releases/tags/'+m[3]);
      if(r.ok){var j=await r.json(),nm=decodeURIComponent(m[4]),a=(j.assets||[]).filter(function(x){return x.name===nm})[0];if(a){o.size=a.size;o.downloads=a.download_count||0;return o}}
    }
    var h=await fetch(url,{method:'HEAD'}),cl=Number(h.headers.get('content-length'));if(cl)o.size=cl;
  }catch(e){}
  return o;
}
